#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# interview-detective's first-run setup. Run it in a terminal: bash setup/wizard.sh
# Saves the cases folder to ~/.config/interview-detective/config.env, which tools/new_case.sh and
# tools/status.py read. Re-running keeps what was saved unless you change it.

TOTAL_STAGES=5

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="${XDG_CONFIG_HOME:-$HOME/.config}/interview-detective/config.env"
mkdir -p "$(dirname "$ENV_FILE")"
NIRI_CONFIG="${XDG_CONFIG_HOME:-$HOME/.config}/niri"
RULE='window-rule {
    match app-id=r#"^dev\.claude\.lab$"#
    open-focused false
}'

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
browser() { uv run "$ROOT/tools/browser.py" "$@"; }

# missing prints one line per requirement that isn't ready, with where to get it.
missing() {
  command -v uv >/dev/null || echo "uv: https://docs.astral.sh/uv/getting-started/installation/"
  command -v chromium >/dev/null || echo "chromium: install your package manager's chromium package"
  if ! command -v gh >/dev/null; then echo "gh: https://cli.github.com/, then run: gh auth login"
  elif ! gh auth status >/dev/null 2>&1; then echo "gh is installed but not logged in: run gh auth login"
  fi
}

# has_rule: the niri config holds a rule for the browser's app-id. -R follows symlinked files, as dotfile
# managers leave them; -r skips them inside folders.
has_rule() { grep -RqsE 'dev\\?\.claude\\?\.lab' "$NIRI_CONFIG"; }

# Sourced by tests/test_wizard.py, which checks the helpers above: stop before the stages.
(return 0 2>/dev/null) && return 0

banner "interview-detective setup"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Requirements"
say "interview-detective runs its tools with uv, opens Chromium for the logins it needs,"
say "and searches GitHub with gh, logged in."
while todo=$(missing) && [[ -n "$todo" ]]; do
  warn "not ready yet:"
  while IFS= read -r line; do step "$line"; done <<<"$todo"
  pause "Install them in another terminal, then press Enter to check again (Ctrl-C to stop)"
done
ok "uv, chromium and gh are ready"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Cases folder"
say "Each interview gets a case folder: your intake, the research, scraped reviews and the report."
say "They hold notes on real people's public work, so they stay on this machine."
note "Enter keeps the default: $HOME/interview-detective"
ask ID_CASES_DIR "Where should cases live?"
ID_CASES_DIR="${ID_CASES_DIR:-$HOME/interview-detective}"
ID_CASES_DIR="${ID_CASES_DIR/#\~/$HOME}"
mkdir -p "$ID_CASES_DIR"
ID_CASES_DIR="$(cd "$ID_CASES_DIR" && pwd)"
write_env ID_CASES_DIR "$ID_CASES_DIR"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "niri window rule"
if [[ -z "${NIRI_SOCKET:-}" ]]; then
  note "You're not on niri, so there's nothing to add: the browser opens wherever your"
  note "compositor puts it, and may take focus when it does."
elif has_rule; then
  ok "your niri config already has a rule for the browser (app-id dev.claude.lab)"
else
  say "Add this rule to your niri config, so the browser opens without taking your focus:"
  printf '\n%s\n\n' "$RULE" | sed 's/^/      /'
  if command -v wl-copy >/dev/null && confirm "Copy it to the clipboard?"; then
    printf '%s\n' "$RULE" | wl-copy && ok "copied"
  fi
  step "Paste it into $NIRI_CONFIG/cfg/agents.kdl (create it if needed) and save."
  note "cfg/agents.kdl keeps the niri rules made for agents in one place."
  step "If config.kdl doesn't include that file yet, add this line to it: include \"./cfg/agents.kdl\""
  note "niri reloads the config when you save."
  while pause "Press Enter once it's saved" && ! has_rule; do
    warn "no rule for dev.claude.lab under $NIRI_CONFIG yet"
    if confirm "Skip it for now?"; then
      SKIPPED+=("the niri window rule: run this wizard again to see it")
      break
    fi
  done
fi
if [[ -n "${NIRI_SOCKET:-}" ]]; then
  if niri validate >/dev/null 2>&1; then ok "niri validate: the config is valid"
  else warn "niri validate reports a problem with your config; run niri validate to see it"
  fi
fi
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "The browser"
say "interview-detective opens its own Chromium, with its own profile, for the sites you log in to."
if [[ -n "${NIRI_SOCKET:-}" ]]; then
  say "It should appear on a new workspace named interview-detective on this screen, and this"
  say "terminal should keep your focus."
fi
pause "Press Enter to open it"
if browser start >/dev/null; then
  if confirm "Did it open like that?"; then
    ok "the browser works"
  else
    SKIPPED+=("the browser took focus or opened elsewhere: check the niri rule (app-id dev.claude.lab)")
    warn "noted; the summary lists it"
  fi
else
  SKIPPED+=("the browser didn't start: run uv run $ROOT/tools/browser.py start to see why")
  warn "it didn't start; the summary lists it"
fi
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Glassdoor login (optional)"
say "Stage 03 reads Glassdoor's interview reviews, which needs you logged in there."
say "You can log in now, or when your first case gets to that stage."
note "The login stays in the browser's own profile, in ~/.cache/interview-detective/browser/."
if confirm "Log in to Glassdoor now?"; then
  browser start https://www.glassdoor.com/ >/dev/null
  step "Switch to the browser's workspace, sign in from the top right of the Glassdoor tab,"
  step "and clear any \"Just a moment\" check."
  pause "Press Enter once you're signed in"
fi
browser stop >/dev/null 2>&1 || true
ok "the browser is closed; it opens again when a case needs it"
pause

finish
say "To start, in Claude Code run /interview-detective:interview-detective,"
say "or just say you have an interview coming up."
note "Cases go in $ID_CASES_DIR. Run this wizard again any time to change that."
printf '\n'
